import{bV as e,aL as t,u as r,G as o}from"./chunks/framework.BidoRKjm.js";const p=JSON.parse('{"title":"关于我","description":"","frontmatter":{"title":"关于我","sidebar":false,"prev":false,"next":false,"comment":false,"articleUpdate":false},"headers":[],"relativePath":"about-me.md","filePath":"about/about-me.md","lastUpdated":1788192834000}'),l={name:"about-me.md"};function i(s,a,n,h,c,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="关于我" tabindex="-1">关于我 <a class="header-anchor" href="#关于我" aria-label="Permalink to &quot;关于我&quot;">​</a></h1><h2 id="个人简介" tabindex="-1">个人简介 <a class="header-anchor" href="#个人简介" aria-label="Permalink to &quot;个人简介&quot;">​</a></h2><p>欢迎来到我的数字自留地！</p><p>我是一名热爱技术的探索者，目前正走在“先运维后开发”的进阶之路上。比起按部就班的理论，我更享受在终端里敲击命令、把零散的服务器和网络搭建成可用服务的成就感。</p><p>这里不仅是我记录技术踩坑与成长的笔记本，也是我向未来技术世界递出的一张名片。</p><h2 id="关于这个网站" tabindex="-1">关于这个网站 <a class="header-anchor" href="#关于这个网站" aria-label="Permalink to &quot;关于这个网站&quot;">​</a></h2><blockquote><p>具体站点详情请看：<a href="/about-site">关于本站</a></p></blockquote><p>你正在浏览的这个网站，本身就是我技术实践的一部分：</p><ul><li>基于 <strong>VitePress</strong> 构建，享受极致的开发与阅读体验。</li><li>采用 <strong>Markdown</strong> 写作，回归内容本质。</li></ul><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><p>如果你想一起探讨技术问题，欢迎通过以下方式联系我：</p><ul><li><strong>GitHub</strong>：<a href="https://github.com/mobei-isfroth" target="_blank" rel="noreferrer">github.com/mobei-isfroth</a></li><li><strong>邮箱</strong>：<a href="mailto:2811218461@qq.com" target="_blank" rel="noreferrer">2811218461@qq.com</a></li><li><strong>QQ</strong>：<a href="https://im.qq.com" target="_blank" rel="noreferrer">2811218461</a></li></ul><h2 id="兴趣爱好" tabindex="-1">兴趣爱好 <a class="header-anchor" href="#兴趣爱好" aria-label="Permalink to &quot;兴趣爱好&quot;">​</a></h2><p>编程 · 羽毛球（又菜又爱玩） · 游戏（喜欢打双人成行、链在一起等多人游戏） · 听歌 · 追剧/番</p><hr>',15)])])}const b=e(l,[["render",i]]);export{p as __pageData,b as default};
